-- Testgrundlage: Nachbildung des produktiven Supabase-Schemas (Stand November 2026).
--
-- Diese Datei bildet den Zustand VOR den Team-Migrationen und -Proposals nach:
-- die sechs Anwendungstabellen aus dem Project Log vom 16.10.2026, die Spalten
-- aus docs/sql-tables.md und den Preflight-Prüfungen der Proposals sowie die von
-- Supabase bereitgestellten Rollen und Auth-Funktionen. Danach spielt
-- tests/support/inventoryStack.mjs die echten Migrationen und Proposals in der
-- Produktionsreihenfolge ein.
--
-- Grenzen der Nachbildung (bewusst dokumentiert):
-- * Es liegt kein Export des echten Schemas vor (`supabase db dump`). Datentypen,
--   Constraint-Namen und Löschregeln der Fremdschlüssel sind plausible Annahmen.
--   Angenommen wird: Spalten mit ausführendem Benutzer (created_by, assigned_by,
--   returned_by, changed_by) verwenden ON DELETE SET NULL, Geräte- und
--   Mitarbeiterbezüge (device_id, employee_id) NO ACTION.
-- * audit_logs hat die Produktionsform laut Preflight vom 24.11.2026 (mit user_id,
--   entity_id und dem Fremdschlüssel audit_logs_user_fk, aber OHNE entity_title),
--   damit die ALTER-Anweisungen des Audit-Proposals tatsächlich ausgeführt werden.
-- * Supabase Auth wird nur nachgestellt: auth.jwt() und auth.uid() lesen die
--   Claims aus request.jwt.claims (wie PostgREST), auth.users und auth.sessions
--   enthalten nur die Spalten, die die Anwendung liest. GoTrue, PostgREST und
--   Edge Functions selbst werden nicht getestet.
-- * Die bestehenden Geräte-Policies (devices_select_managed,
--   devices_insert_managed, devices_update_managed) sind rekonstruiert, damit der
--   Preflight des Geräte-Status-Proposals dieselben Voraussetzungen vorfindet.

-- 1. Von Supabase bereitgestellte Datenbankrollen
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;

-- 2. Supabase Auth (Nachbildung)
create schema auth;
grant usage on schema auth to anon, authenticated, service_role;

create function auth.jwt() returns jsonb
language sql stable
as $$
  select coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb)
$$;

create function auth.uid() returns uuid
language sql stable
as $$
  select nullif(auth.jwt() ->> 'sub', '')::uuid
$$;

create table auth.users (
  id uuid primary key default gen_random_uuid(),
  email text unique,
  banned_until timestamptz,
  raw_user_meta_data jsonb default '{}'::jsonb,
  raw_app_meta_data jsonb default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create table auth.sessions (
  id uuid primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default clock_timestamp(),
  not_after timestamptz
);

-- 3. Anwendungstabellen im Schema public
create table public.roles (
  id bigint generated by default as identity primary key,
  name text not null,
  description text,
  constraint roles_name_unique unique (name)
);

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  role_id bigint references public.roles (id),
  first_name text,
  last_name text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.devices (
  id uuid primary key default gen_random_uuid(),
  status text default 'available'
    check (status in ('available', 'assigned', 'defective', 'maintenance', 'retired')),
  asset_tag text not null unique,
  device_type text,
  manufacture text,
  model text,
  serial_number text unique,
  name text,
  operating_system text,
  processor text,
  ram_gb integer,
  disk_space_gb integer,
  location text,
  device_usage text,
  purchased_at date,
  start_of_use date,
  maintenance_end date,
  description text,
  comments text,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.assignments (
  id uuid primary key default gen_random_uuid(),
  device_id uuid not null references public.devices (id),
  employee_id uuid not null references public.profiles (id),
  assigned_by uuid references public.profiles (id) on delete set null,
  assigned_at timestamptz not null default now(),
  returned_at timestamptz,
  returned_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  constraint assignments_returned_after_assigned
    check (returned_at is null or returned_at >= assigned_at)
);

-- Bereits seit dem 16.10.2026: pro Gerät höchstens eine aktive Zuweisung.
create unique index assignments_one_active_per_device
  on public.assignments (device_id)
  where returned_at is null;

create table public.device_status_history (
  id uuid primary key default gen_random_uuid(),
  device_id uuid not null references public.devices (id),
  old_status text
    check (old_status in ('available', 'assigned', 'defective', 'maintenance', 'retired')),
  new_status text not null
    check (new_status in ('available', 'assigned', 'defective', 'maintenance', 'retired')),
  changed_by uuid references public.profiles (id) on delete set null,
  changed_at timestamptz not null default now()
);

-- Form wie in Produktion (Preflight-Ergebnis vom 24.11.2026): user_id und entity_id
-- vorhanden, Fremdschlüssel audit_logs_user_fk ohne Löschregel, KEIN entity_title.
create table public.audit_logs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid,
  action text,
  entity_type text,
  entity_id uuid,
  details jsonb,
  created_at timestamptz not null default now(),
  constraint audit_logs_user_fk foreign key (user_id) references public.profiles (id)
);

-- 4. Standardrechte, wie Supabase sie für das Schema public vergibt
grant usage on schema public to anon, authenticated, service_role;
grant all on all tables in schema public to anon, authenticated, service_role;
grant all on all sequences in schema public to anon, authenticated, service_role;

-- 5. Row Level Security auf allen sechs Anwendungstabellen
alter table public.roles enable row level security;
alter table public.profiles enable row level security;
alter table public.devices enable row level security;
alter table public.assignments enable row level security;
alter table public.device_status_history enable row level security;
alter table public.audit_logs enable row level security;

-- 6. Rekonstruierte Team-Policies für die Geräteverwaltung.
-- Profile und Rollen erhalten ihre Policies erst durch die Migration
-- 20261026080000_auth_profile_read_policies.sql (deren Preflight verlangt,
-- dass dort noch keine Policies existieren).
create policy devices_select_managed on public.devices
  for select to authenticated
  using (exists (
    select 1 from public.profiles p join public.roles r on r.id = p.role_id
    where p.id = (select auth.uid()) and r.name in ('admin', 'super_admin', 'device_manager')
  ));

create policy devices_insert_managed on public.devices
  for insert to authenticated
  with check (exists (
    select 1 from public.profiles p join public.roles r on r.id = p.role_id
    where p.id = (select auth.uid()) and r.name in ('admin', 'super_admin', 'device_manager')
  ));

create policy devices_update_managed on public.devices
  for update to authenticated
  using (exists (
    select 1 from public.profiles p join public.roles r on r.id = p.role_id
    where p.id = (select auth.uid()) and r.name in ('admin', 'super_admin', 'device_manager')
  ))
  with check (exists (
    select 1 from public.profiles p join public.roles r on r.id = p.role_id
    where p.id = (select auth.uid()) and r.name in ('admin', 'super_admin', 'device_manager')
  ));

create policy device_status_history_select_managed on public.device_status_history
  for select to authenticated
  using (exists (
    select 1 from public.profiles p join public.roles r on r.id = p.role_id
    where p.id = (select auth.uid()) and r.name in ('admin', 'super_admin', 'device_manager')
  ));

-- 7. Rollen wie in Produktion (super_admin entsteht erst durch das SuperAdmin-Proposal)
insert into public.roles (name, description) values
  ('admin', 'Administrator'),
  ('device_manager', 'Gerätemanager'),
  ('employee', 'Mitarbeiter');
